 import { bootstrapApplication } from '@angular/platform-browser';
 import { Component, OnInit } from '@angular/core';
 import { FormsModule } from '@angular/forms';

 type Session = { email: string; name: string; roles: string[] };
 type Equipment = {
   assetId: string;
   name: string;
   trackingMode: string;
   total: number;
   available: number;
   checkedOut: number;
   damaged: number;
   condition: string;
   isAvailable: boolean | null;
   approvalRequired: boolean;
   currentCustodian: string | null;
   dueAt: string | null;
   isOverdue: boolean;
   hasUnresolvedCustody: boolean;
   approverEmails: string[];
 };

 @Component({
   selector: 'app-root',
   standalone: true,
   imports: [FormsModule],
   template: `
     <main>
       <h1>Equipment Tracking</h1>
       @if (session; as current) {
         <p>Signed in as <strong>{{ current.name }}</strong> ({{ current.roles.join(', ') }})</p>
         <button type="button" (click)="logout()">Sign out</button>
         <p class="success">Your local review session is active.</p>
         <section aria-labelledby="catalogue-heading">
           <h2 id="catalogue-heading">Equipment catalogue</h2>
           <form class="search" (ngSubmit)="searchCatalogue()">
             <label for="catalogue-search">Search by name or asset ID</label>
             <div class="search-row">
               <input id="catalogue-search" name="search" [(ngModel)]="search" autocomplete="off">
               <button type="submit" [disabled]="catalogueLoading">Search</button>
               @if (search) { <button type="button" (click)="clearSearch()">Clear</button> }
             </div>
           </form>
           @if (catalogueLoading) { <p>Loading catalogue…</p> }
           @if (catalogueError) { <p class="error" role="alert">{{ catalogueError }}</p> }
           @if (!catalogueLoading && !catalogueError && equipment.length === 0) {
             <p>{{ search.trim() ? 'No equipment matches your search.' : 'No equipment has been added.' }}</p>
           }
           @if (equipment.length > 0) {
             <ul class="catalogue">
               @for (item of equipment; track item.assetId) {
                 <li><button type="button" class="equipment-link" (click)="selectEquipment(item)">
                   <strong>{{ item.name }}</strong> ({{ item.assetId }})
                 </button></li>
               }
             </ul>
           }
           @if (selectedEquipment; as item) {
             <article class="detail" aria-labelledby="detail-heading">
               <h3 id="detail-heading">{{ item.name }}</h3>
               <p><strong>Asset ID:</strong> {{ item.assetId }}</p>
               <p><strong>Tracking:</strong> {{ item.trackingMode }}</p>
               @if (item.trackingMode === 'Pooled') {
                 <p><strong>Total:</strong> {{ item.total }} · <strong>Available:</strong> {{ item.available }} ·
                   <strong>Checked-out:</strong> {{ item.checkedOut }} · <strong>Damaged:</strong> {{ item.damaged }}</p>
               } @else {
                 <p><strong>Availability:</strong> {{ item.isAvailable ? 'Available' : 'Unavailable' }}</p>
                 <p><strong>Condition:</strong> {{ item.condition }}</p>
                 <p><strong>Current custodian:</strong> {{ item.currentCustodian ?? 'None recorded' }}</p>
                 <p><strong>Due:</strong> {{ item.dueAt ?? 'None recorded' }}
                   @if (item.isOverdue) { <span class="warning">(overdue)</span> }</p>
                 <p><strong>Unresolved custody:</strong> {{ item.hasUnresolvedCustody ? 'Yes' : 'No' }}</p>
               }
               <p><strong>Approval:</strong> {{ item.approvalRequired ? 'Restricted' : 'Not restricted' }}</p>
               @if (item.approverEmails.length > 0) { <p><strong>Approvers:</strong> {{ item.approverEmails.join(', ') }}</p> }
             </article>
           }
         </section>
         @if (canCreate) {
           <section aria-labelledby="create-heading">
             <h2 id="create-heading">Add equipment</h2>
             <form (ngSubmit)="createEquipment()" #equipmentForm="ngForm">
               <label for="equipment-name">Name</label>
               <input id="equipment-name" name="equipmentName" [(ngModel)]="equipmentName" required>
               <label for="asset-id">Asset ID</label>
               <input id="asset-id" name="assetId" [(ngModel)]="assetId" required>
               <label for="tracking-mode">Tracking mode</label>
               <select id="tracking-mode" name="trackingMode" [(ngModel)]="trackingMode">
                 <option value="Individual">Individual</option>
                 <option value="Pooled">Pooled</option>
               </select>
               @if (trackingMode === 'Pooled') {
                 <label for="total">Total quantity</label>
                 <input id="total" name="total" type="number" min="1" step="1" [(ngModel)]="total" required>
               }
               <button type="submit" [disabled]="equipmentForm.invalid || creating">{{ creating ? 'Adding…' : 'Add equipment' }}</button>
             </form>
             @if (createError) { <p class="error" role="alert">{{ createError }}</p> }
           </section>
         }
       } @else {
         <form (ngSubmit)="login()" #loginForm="ngForm">
           <label for="email">Email</label>
           <input id="email" name="email" type="email" [(ngModel)]="email" required autocomplete="username">
           <label for="password">Password</label>
           <input id="password" name="password" type="password" [(ngModel)]="password" required autocomplete="current-password">
           <button type="submit" [disabled]="loginForm.invalid || loading">{{ loading ? 'Signing in…' : 'Sign in' }}</button>
         </form>
         @if (error) { <p class="error" role="alert">{{ error }}</p> }
       }
     </main>
   `,
   styles: [`main{font-family:system-ui;max-width:32rem;margin:4rem auto;padding:1rem}h1{color:#164e63}form{display:grid;gap:.5rem}input{font:inherit;padding:.5rem;margin-bottom:.75rem}button{font:inherit;padding:.55rem .8rem;width:max-content}.error{color:#b42318}.success{color:#067647}`]
 })
 class AppComponent implements OnInit {
   email = '';
   password = '';
   session: Session | null = null;
   error = '';
   loading = false;
   equipment: Equipment[] = [];
   selectedEquipment: Equipment | null = null;
   search = '';
   catalogueLoading = false;
   catalogueError = '';
   equipmentName = '';
   assetId = '';
   trackingMode = 'Individual';
   total: number | null = null;
   creating = false;
   createError = '';

   get canCreate(): boolean {
     return this.session?.roles.some(role => role === 'Office Staff' || role === 'Manager/Admin') ?? false;
   }

   async ngOnInit(): Promise<void> {
     try {
       const response = await fetch('/api/auth/me', { credentials: 'same-origin' });
       if (response.ok) {
         this.session = await response.json() as Session;
         await this.loadCatalogue();
       }
     } catch {
       this.error = 'The local sign-in service is unavailable.';
     }

   }

   async loadCatalogue(): Promise<void> {
     this.catalogueLoading = true;
     this.catalogueError = '';
     try {
       const query = this.search.trim() ? `?search=${encodeURIComponent(this.search.trim())}` : '';
       const response = await fetch(`/api/equipment${query}`, { credentials: 'same-origin' });
       if (!response.ok) {
         this.equipment = [];
         this.selectedEquipment = null;
         if (response.status === 401) {
           this.session = null;
           this.catalogueError = 'Please sign in again.';
         } else {
           this.catalogueError = 'Unable to load the equipment catalogue.';
         }
         return;
       }
       this.equipment = await response.json() as Equipment[];
       this.selectedEquipment = null;
     } catch {
       this.equipment = [];
       this.selectedEquipment = null;
       this.catalogueError = 'The local equipment service is unavailable.';
     } finally {
       this.catalogueLoading = false;
     }

   }

   async searchCatalogue(): Promise<void> {
     await this.loadCatalogue();
   }

   clearSearch(): void {
     this.search = '';
     void this.loadCatalogue();
   }

   selectEquipment(item: Equipment): void {
     this.selectedEquipment = item;
   }

   async createEquipment(): Promise<void> {
     this.createError = '';
     if (!this.equipmentName.trim() || !this.assetId.trim() ||
       (this.trackingMode === 'Pooled' && (!Number.isInteger(this.total) || (this.total ?? 0) <= 0))) {
       this.createError = this.trackingMode === 'Pooled'
         ? 'Enter a name, asset ID, and positive whole-number total.'
         : 'Enter a name and asset ID.';
       return;
     }
     this.creating = true;
     try {
       const response = await fetch('/api/equipment', {
         method: 'POST',
         headers: { 'Content-Type': 'application/json' },
         credentials: 'same-origin',
         body: JSON.stringify({
           name: this.equipmentName,
           assetId: this.assetId,
           trackingMode: this.trackingMode,
           total: this.trackingMode === 'Pooled' ? this.total : null
         })
       });
       if (!response.ok) {
         if (response.status === 401) {
           this.session = null;
           this.equipment = [];
           this.selectedEquipment = null;
         }
         const body = await response.json().catch(() => null) as { error?: string } | null;
         this.createError = body?.error ?? 'Unable to add equipment.';
         return;
       }
       this.equipmentName = '';
       this.assetId = '';
       this.total = null;
       await this.loadCatalogue();
     } catch {
       this.createError = 'The local equipment service is unavailable.';
     } finally {
       this.creating = false;
     }
   }

   async login(): Promise<void> {
     this.error = '';
     this.loading = true;
     try {
       const response = await fetch('/api/auth/login', {
         method: 'POST',
         headers: { 'Content-Type': 'application/json' },
         credentials: 'same-origin',
         body: JSON.stringify({ email: this.email, password: this.password })
       });
       if (!response.ok) {
         this.error = 'Sign-in failed. Check your email and password.';
         return;
       }
       this.session = await response.json() as Session;
       this.password = '';
       await this.loadCatalogue();
     } catch {
       this.error = 'The local sign-in service is unavailable.';
     } finally {
       this.loading = false;
     }
   }

   async logout(): Promise<void> {
     this.error = '';
     try {
       const response = await fetch('/api/auth/logout', { method: 'POST', credentials: 'same-origin' });
       if (!response.ok) {
         this.error = 'Sign-out failed. Please try again.';
         return;
       }
       this.session = null;
       this.equipment = [];
       this.selectedEquipment = null;
     } catch {
       this.error = 'The local sign-in service is unavailable.';
     }
   }
 }
 bootstrapApplication(AppComponent).catch(console.error);

